"""Pinning as a detector of abelianness: the cyclic cubic against an S_3 cubic.

Full pinning of a residue channel, I(p mod m ; T) = H(T), is equivalent to the
splitting type being a function of p mod m.  For an abelian field this happens
at the conductor; for a non-abelian field it can never happen, for any modulus.

This demo estimates, from the primes below a bound, the channel invariants of

  * the cyclic cubic field of conductor 7, defined by x^3 + x^2 - 2x - 1
    (splitting types: 3 roots mod p, or 0 roots mod p), and
  * the S_3 cubic field of discriminant -23, defined by x^3 - x - 1
    (splitting types: 3 roots, 1 root, or 0 roots mod p),

for a range of moduli m, and prints the deficit H(T) - I(p mod m ; T).

Expected behaviour, and what the output shows:
  * the cyclic cubic has deficit ~0 exactly at m = 7 (and its multiples): the
    channel is fully pinned by the conductor;
  * the S_3 cubic never reaches deficit 0.  At m = 23 the quadratic resolvent
    field Q(sqrt(-23)) is pinned, so the residue reveals about 1 bit --- namely
    whether the Frobenius is a transposition --- but the remaining ~0.45 bits
    distinguishing "splits completely" from "inert" are unreachable, because
    that distinction is governed by the class field theory of Q(sqrt(-23))
    (equivalently by the representation of p by x^2 + xy + 6y^2), not by any
    congruence.
"""

from __future__ import annotations

from math import log2
from typing import Dict, List, Sequence, Tuple


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * limit
    sieve[0:2] = [False, False]
    for n in range(2, int(limit ** 0.5) + 1):
        if sieve[n]:
            for k in range(n * n, limit, n):
                sieve[k] = False
    return [n for n in range(limit) if sieve[n]]


def eta(x: float) -> float:
    return 0.0 if x <= 0.0 else -x * log2(x)


def entropy(weights) -> float:
    return sum(eta(w) for w in weights)


def mutual_information(joint: Dict[Tuple[int, int], float]) -> float:
    mx: Dict[int, float] = {}
    my: Dict[int, float] = {}
    for (x, y), w in joint.items():
        mx[x] = mx.get(x, 0.0) + w
        my[y] = my.get(y, 0.0) + w
    return entropy(mx.values()) + entropy(my.values()) - entropy(joint.values())


def root_count(coeffs: Sequence[int], p: int) -> int:
    """Number of roots in F_p of the polynomial with ascending coefficients."""
    count = 0
    for x in range(p):
        acc = 0
        for c in reversed(coeffs):
            acc = (acc * x + c) % p
        if acc == 0:
            count += 1
    return count


def channel(coeffs: Sequence[int], bad: Sequence[int], m: int, limit: int):
    """Empirical (H(T), I(p mod m ; T), deficit) from the primes below `limit`."""
    joint: Dict[Tuple[int, int], float] = {}
    total = 0
    for p in primes_up_to(limit):
        if p in bad or p % m == 0:
            continue
        key = (p % m, root_count(coeffs, p))
        joint[key] = joint.get(key, 0.0) + 1.0
        total += 1
    joint = {k: v / total for k, v in joint.items()}
    my: Dict[int, float] = {}
    for (_, t), w in joint.items():
        my[t] = my.get(t, 0.0) + w
    h = entropy(my.values())
    info = mutual_information(joint)
    return h, info, h - info


CYCLIC = (-1, -2, 1, 1)   # x^3 + x^2 - 2x - 1 : cyclic, conductor 7
S3 = (-1, -1, 0, 1)       # x^3 - x - 1        : S_3, discriminant -23


def main(limit: int = 6000) -> None:
    print(f"primes below {limit}; deficit = H(T) - I(p mod m ; T), in bits\n")
    header = f"{'m':>4} | {'cyclic cubic (cond. 7)':^34} | {'S_3 cubic (disc. -23)':^34}"
    print(header)
    print(f"{'':>4} | {'H(T)':>9} {'I':>9} {'deficit':>12} | {'H(T)':>9} {'I':>9} {'deficit':>12}")
    print("-" * len(header))
    for m in (3, 5, 7, 9, 11, 14, 21, 23, 46, 69):
        h1, i1, d1 = channel(CYCLIC, (7,), m, limit)
        h2, i2, d2 = channel(S3, (23,), m, limit)
        flag = "   <-- fully pinned" if d1 < 5e-3 else ""
        print(f"{m:4d} | {h1:9.4f} {i1:9.4f} {d1:12.4f} | {h2:9.4f} {i2:9.4f} {d2:12.4f}{flag}")
    print("\nThe cyclic cubic reaches deficit 0 at its conductor m = 7 and at every")
    print("multiple of it.  The S_3 cubic never does: at m = 23 it gains the one bit")
    print("carried by the quadratic resolvent and then stops, leaving a stubborn")
    print("positive deficit at every modulus --- the information-theoretic signature")
    print("of a non-abelian Galois group.")


if __name__ == "__main__":
    main()

