function FACTOR23(m = num/den):
    i <- 0 ; j <- 0
    for (p, sign) in [(num, +1), (den, -1)]:
        while p mod 2 = 0 : p <- p/2 ; i <- i + sign
        while p mod 3 = 0 : p <- p/3 ; j <- j + sign
        if p != 1 : ERROR 'mass is not 2-3 smooth'
    return (i, j)

function ETA_EXACT(m):
    if m = 0 : return (0, 0)
    (i, j) <- FACTOR23(m)
    return (-m*i, -m*j)          // -m log2 m = -m (i + j log2 3)

function ENTROPY_EXACT(weights):
    acc <- (0,0)
    for w in weights : acc <- acc + ETA_EXACT(w)
    return acc

function MUTUAL_INFORMATION_EXACT(w):
    wA <- row sums of w ; wB <- column sums of w
    return ENTROPY_EXACT(wA) + ENTROPY_EXACT(wB) - ENTROPY_EXACT(w)

