"""Exact closed-form entropy and mutual information for 2-adic/3-adic channels.

Every probability appearing in the conductor-7 type channels has the form
2^i * 3^j with i, j in Z (e.g. 1/6, 1/9, 1/18, 1/3, 2/3, 4/9, 2/9).  For such a
mass m = 2^i 3^j we have

    eta(m) = -m * log2(m) = -(2^i 3^j) * (i + j * log2 3),

so every entropy in the theory is an exact element of Q + Q*log2(3).  This
module implements that arithmetic, returning closed forms rather than floats.
"""

from __future__ import annotations

from fractions import Fraction
from itertools import product
from math import log2
from typing import Dict, Hashable, Iterable, List, Tuple


class Exact:
    """The number a + b * log2(3) with a, b rational."""

    __slots__ = ("a", "b")

    def __init__(self, a: Fraction = Fraction(0), b: Fraction = Fraction(0)) -> None:
        self.a = Fraction(a)
        self.b = Fraction(b)

    def __add__(self, other: "Exact") -> "Exact":
        return Exact(self.a + other.a, self.b + other.b)

    def __sub__(self, other: "Exact") -> "Exact":
        return Exact(self.a - other.a, self.b - other.b)

    def __rmul__(self, c: Fraction) -> "Exact":
        return Exact(Fraction(c) * self.a, Fraction(c) * self.b)

    def value(self) -> float:
        return float(self.a) + float(self.b) * log2(3.0)

    def __repr__(self) -> str:
        return f"{self.a} + ({self.b})*log2(3)  = {self.value():.9f}"


def factor_23(m: Fraction) -> Tuple[int, int]:
    """Write m = 2^i * 3^j; raise if m has another prime factor."""
    num, den = m.numerator, m.denominator
    i = j = 0
    for p, sign in ((num, 1), (den, -1)):
        while p % 2 == 0:
            p //= 2
            i += sign
        while p % 3 == 0:
            p //= 3
            j += sign
        if p != 1:
            raise ValueError(f"mass {m} is not of the form 2^i 3^j")
    return i, j


def eta_exact(m: Fraction) -> Exact:
    """-m log2 m as an element of Q + Q log2 3."""
    if m == 0:
        return Exact()
    i, j = factor_23(m)
    return Exact(-m * i, -m * j)


def entropy_exact(weights: Iterable[Fraction]) -> Exact:
    total = Exact()
    for w in weights:
        total = total + eta_exact(w)
    return total


def mutual_information_exact(joint: Dict[Tuple[Hashable, Hashable], Fraction]) -> Exact:
    mx: Dict[Hashable, Fraction] = {}
    my: Dict[Hashable, Fraction] = {}
    for (x, y), w in joint.items():
        mx[x] = mx.get(x, Fraction(0)) + w
        my[y] = my.get(y, Fraction(0)) + w
    return entropy_exact(mx.values()) + entropy_exact(my.values()) - entropy_exact(joint.values())


UNITS7: Tuple[int, ...] = (1, 2, 3, 4, 5, 6)


def res_type(u: int) -> bool:
    """True iff the residue class u mod 7 is of split type (u = +-1)."""
    return u % 7 in (1, 6)


def prime_channel() -> Dict[Tuple[int, bool], Fraction]:
    return {(u, res_type(u)): Fraction(1, 6) for u in UNITS7}


def semiprime_channel(ordered: bool) -> Dict[Tuple[int, Hashable], Fraction]:
    joint: Dict[Tuple[int, Hashable], Fraction] = {}
    for u, v in product(UNITS7, repeat=2):
        label = (res_type(u), res_type(v)) if ordered else int(res_type(u)) + int(res_type(v))
        key = ((u * v) % 7, label)
        joint[key] = joint.get(key, Fraction(0)) + Fraction(1, 36)
    return joint


def report() -> List[Tuple[str, Exact]]:
    rt = prime_channel()
    su = semiprime_channel(ordered=False)
    so = semiprime_channel(ordered=True)

    def out_marginal(joint):
        my: Dict[Hashable, Fraction] = {}
        for (_, y), w in joint.items():
            my[y] = my.get(y, Fraction(0)) + w
        return entropy_exact(my.values())

    h_t = out_marginal(rt)
    i_rt = mutual_information_exact(rt)
    h_s = out_marginal(su)
    i_s = mutual_information_exact(su)
    h_o = out_marginal(so)
    i_o = mutual_information_exact(so)
    return [
        ("H(T)", h_t),
        ("I(p mod 7 ; T)", i_rt),
        ("pinning gap I - H(T)", i_rt - h_t),
        ("H(S)", h_s),
        ("I(N ; S)", i_s),
        ("semiprime deficit H(S) - I", h_s - i_s),
        ("H(T_p,T_q)", h_o),
        ("I(N ; (T_p,T_q))", i_o),
        ("which-factor information", i_o - i_s),
        ("which-factor entropy H(T_p,T_q) - H(S)", h_o - h_s),
    ]


if __name__ == "__main__":
    for name, val in report():
        print(f"{name:42s} {val}")

"""Trace-order root criterion via Chebyshev-type recursions.

For an odd prime conductor m, let Psi_m be the minimal polynomial of
zeta_m + zeta_m^{-1}, of degree (m-1)/2.  The Chebyshev-type coefficients

    A_0 = 0,  A_1 = 1,  A_{n+2}(t) = t A_{n+1}(t) - A_n(t)

satisfy  C(t)^{n+1} = A_{n+1}(t) C(t) - A_n(t) I  for the companion matrix
C(t) = [[t,-1],[1,0]] of Y^2 - tY + 1, which has determinant 1 and trace t.
Hence C(t) has order exactly m iff A_m(t) = 0 and A_{m-1}(t) = -1, and such an
element of SL_2(F_p) exists iff m | p^2 - 1, i.e. iff p = +-1 (mod m).

Three routines are provided, of increasing speed:
  * search_trace(m, p)     -- O(p * m) field operations, brute force over t;
  * has_order_m(m, p)      -- O(1), the closed criterion m | p^2 - 1;
  * psi_has_root(m, p)     -- O(p * deg Psi_m), independent brute force,
                              used to cross-check the two above.
"""

from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

# minimal polynomials of zeta_m + zeta_m^{-1}, coefficients in ascending degree
PSI: Dict[int, Tuple[int, ...]] = {
    3: (1, 1),                        # x + 1
    5: (-1, 1, 1),                    # x^2 + x - 1
    7: (-1, -2, 1, 1),                # x^3 + x^2 - 2x - 1
    11: (1, 3, -3, -4, 1, 1),         # x^5 + x^4 - 4x^3 - 3x^2 + 3x + 1
    13: (-1, 3, 6, -4, -5, 1, 1),      # x^6 + x^5 - 5x^4 - 4x^3 + 6x^2 + 3x - 1
}


def cheb_A(t: int, n: int, p: int) -> int:
    """A_n(t) mod p, computed by the three-term recursion in O(n) steps."""
    a, b = 0 % p, 1 % p
    for _ in range(n):
        a, b = b, (t * b - a) % p
    return a


def search_trace(m: int, p: int) -> Optional[int]:
    """Return some t in F_p with A_m(t) = 0 and A_{m-1}(t) = -1, or None."""
    for t in range(p):
        if cheb_A(t, m, p) == 0 and cheb_A(t, m - 1, p) == (p - 1) % p:
            return t
    return None


def has_order_m(m: int, p: int) -> bool:
    """The closed criterion: an order-m element of SL_2(F_p) exists iff m | p^2 - 1."""
    return (p * p - 1) % m == 0


def psi_has_root(m: int, p: int) -> bool:
    """Does Psi_m have a root modulo p?  (Horner evaluation at every point.)"""
    coeffs: Sequence[int] = PSI[m]
    for x in range(p):
        acc = 0
        for c in reversed(coeffs):
            acc = (acc * x + c) % p
        if acc == 0:
            return True
    return False


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * limit
    sieve[0:2] = [False, False]
    for n in range(2, int(limit ** 0.5) + 1):
        if sieve[n]:
            for k in range(n * n, limit, n):
                sieve[k] = False
    return [n for n in range(limit) if sieve[n]]


def cross_check(limit: int = 300) -> int:
    """Verify the three criteria agree for every available m and every odd p < limit."""
    checks = 0
    for m in PSI:
        if m == 3:
            continue
        for p in primes_up_to(limit):
            if p in (2, m):
                continue
            a = search_trace(m, p) is not None
            b = has_order_m(m, p)
            c = psi_has_root(m, p)
            assert a == b == c, (m, p, a, b, c)
            checks += 1
    return checks


if __name__ == "__main__":
    n = cross_check(200)
    print(f"{n} agreements between the trace search, the criterion m | p^2 - 1,")
    print("and a direct root search for Psi_m, over m = 5, 7, 11, 13.")
    for m in (5, 7, 11, 13):
        good = [p for p in primes_up_to(120) if p not in (2, m) and has_order_m(m, p)]
        print(f"  m = {m:2d}:  Psi_m has a root mod p for p in {good}")

