INPUT : joint law w : A x B -> R_{>=0} with total mass 1
OUTPUT: ceiling H(w_B), transmitted I(w), deficit, and the pinning verdict

function IS_DETERMINISTIC(w):
    seen <- empty map
    for each (x, y) with w(x,y) > 0:
        if x in seen and seen[x] != y : return FALSE
        seen[x] <- y
    return TRUE                                // support is a graph

function MUTUAL_INFORMATION(w):
    wA <- row sums ; wB <- column sums
    return H(wA) + H(wB) - H(w)                // H(v) = sum of -v log2 v

function PINNING_REPORT(w):
    ceiling <- H(column sums of w)
    info    <- MUTUAL_INFORMATION(w)
    deficit <- ceiling - info                  // always >= 0
    det     <- IS_DETERMINISTIC(w)
    return { ceiling, info, deficit,
             fully_pinned : deficit = 0,
             deterministic: det,
             consistent   : det = (deficit = 0) }

