"""Deterministic-channel pinning test and deficit computation.

A finite channel with joint law w on A x B is FULLY PINNED when its mutual
information attains the data-processing ceiling, I(w) = H(w_B).  The structural
theorem behind the whole development is:

    I(w) <= H(w_B) always, with equality exactly when the support of w is the
    graph of a function A -> B (each input row is concentrated at one output).

So pinning can be decided combinatorially, without evaluating a single
logarithm: scan the support and check that every input row meets at most one
output column.  This routine does that, and if the channel is not pinned it
returns the exact numerical deficit H(w_B) - I(w) as the price of the failure.

Complexity: O(|support|) for the structural test, O(|A||B|) for the deficit.
"""

from __future__ import annotations

from math import log2
from typing import Dict, Hashable, Tuple


def eta(x: float) -> float:
    return 0.0 if x <= 0.0 else -x * log2(x)


def entropy(weights) -> float:
    return sum(eta(w) for w in weights)


def marginals(joint: Dict[Tuple[Hashable, Hashable], float]):
    mx: Dict[Hashable, float] = {}
    my: Dict[Hashable, float] = {}
    for (x, y), w in joint.items():
        if w <= 0.0:
            continue
        mx[x] = mx.get(x, 0.0) + w
        my[y] = my.get(y, 0.0) + w
    return mx, my


def mutual_information(joint: Dict[Tuple[Hashable, Hashable], float]) -> float:
    mx, my = marginals(joint)
    return entropy(mx.values()) + entropy(my.values()) - entropy(joint.values())


def is_deterministic(joint: Dict[Tuple[Hashable, Hashable], float]) -> bool:
    """Is the support of the joint law the graph of a function of the input?"""
    seen: Dict[Hashable, Hashable] = {}
    for (x, y), w in joint.items():
        if w <= 0.0:
            continue
        if x in seen and seen[x] != y:
            return False
        seen[x] = y
    return True


def pinning_report(joint: Dict[Tuple[Hashable, Hashable], float]) -> Dict[str, object]:
    """Full diagnostic: ceiling, transmitted information, deficit, verdict."""
    _, my = marginals(joint)
    ceiling = entropy(my.values())
    info = mutual_information(joint)
    deterministic = is_deterministic(joint)
    deficit = ceiling - info
    return {
        "output_entropy_ceiling": ceiling,
        "mutual_information": info,
        "deficit": deficit,
        "deterministic": deterministic,
        "fully_pinned": abs(deficit) < 1e-12,
        "consistent": deterministic == (abs(deficit) < 1e-12),
    }


if __name__ == "__main__":
    from itertools import product

    units = (1, 2, 3, 4, 5, 6)
    typ = lambda u: u % 7 in (1, 6)

    prime = {(u, typ(u)): 1 / 6 for u in units}

    semi: Dict[Tuple[int, int], float] = {}
    for u, v in product(units, repeat=2):
        key = ((u * v) % 7, int(typ(u)) + int(typ(v)))
        semi[key] = semi.get(key, 0.0) + 1 / 36

    for name, ch in (("single prime", prime), ("semiprime", semi)):
        rep = pinning_report(ch)
        print(f"{name:14s} ceiling={rep['output_entropy_ceiling']:.6f} "
              f"I={rep['mutual_information']:.6f} deficit={rep['deficit']:.6f} "
              f"deterministic={rep['deterministic']} pinned={rep['fully_pinned']}")

