"""Deficit spectrum: an abelian field is pinned at its conductor, an S_3 field never.

For each modulus m the script estimates, from the primes below a bound, the
deficit H(T) - I(p mod m ; T) for two cubic fields:
  * x^3 + x^2 - 2x - 1  (cyclic, conductor 7): the deficit collapses to 0 at
    every multiple of 7;
  * x^3 - x - 1         (S_3, discriminant -23): the deficit drops at multiples
    of 23 --- the quadratic resolvent is pinned --- but never reaches 0.
The output is a bar chart of the two deficit spectra.
"""

from __future__ import annotations

from math import log2
from typing import Dict, List, Sequence, Tuple

import matplotlib.pyplot as plt
import numpy as np


def primes_up_to(limit: int) -> List[int]:
    sieve = [True] * limit
    sieve[0:2] = [False, False]
    for n in range(2, int(limit ** 0.5) + 1):
        if sieve[n]:
            for k in range(n * n, limit, n):
                sieve[k] = False
    return [n for n in range(limit) if sieve[n]]


def eta(x: float) -> float:
    return 0.0 if x <= 0 else -x * log2(x)


def root_count(coeffs: Sequence[int], p: int) -> int:
    c = 0
    for x in range(p):
        acc = 0
        for a in reversed(coeffs):
            acc = (acc * x + a) % p
        if acc == 0:
            c += 1
    return c


def deficit(coeffs: Sequence[int], bad: Sequence[int], m: int, primes: Sequence[int],
            types: Dict[int, int]) -> float:
    joint: Dict[Tuple[int, int], float] = {}
    total = 0
    for p in primes:
        if p in bad or p % m == 0:
            continue
        key = (p % m, types[p])
        joint[key] = joint.get(key, 0.0) + 1.0
        total += 1
    joint = {k: v / total for k, v in joint.items()}
    mx: Dict[int, float] = {}
    my: Dict[int, float] = {}
    for (x, y), w in joint.items():
        mx[x] = mx.get(x, 0.0) + w
        my[y] = my.get(y, 0.0) + w
    hx = sum(map(eta, mx.values()))
    hy = sum(map(eta, my.values()))
    hj = sum(map(eta, joint.values()))
    return hy - (hx + hy - hj)


def main(limit: int = 6000) -> None:
    primes = [p for p in primes_up_to(limit) if p > 2]
    cyclic, s3 = (-1, -2, 1, 1), (-1, -1, 0, 1)
    tc = {p: root_count(cyclic, p) for p in primes}
    ts = {p: root_count(s3, p) for p in primes}

    moduli = [3, 5, 7, 9, 11, 13, 14, 21, 23, 28, 46, 69]
    dc = [deficit(cyclic, (7,), m, primes, tc) for m in moduli]
    ds = [deficit(s3, (23,), m, primes, ts) for m in moduli]

    x = np.arange(len(moduli))
    fig, ax = plt.subplots(figsize=(10, 4.6))
    ax.bar(x - 0.2, dc, width=0.4, label="cyclic cubic, conductor 7 (abelian)")
    ax.bar(x + 0.2, ds, width=0.4, label="$x^3-x-1$, discriminant $-23$ ($S_3$)")
    ax.set_xticks(x)
    ax.set_xticklabels([str(m) for m in moduli])
    ax.set_xlabel("modulus $m$")
    ax.set_ylabel("deficit  $H(T) - I(p \\bmod m ; T)$   (bits)")
    ax.set_title("Pinning detects abelianness: the deficit spectrum")
    ax.axhline(0, color="black", lw=0.8)
    ax.legend()
    fig.tight_layout()
    fig.savefig("deficit_spectrum.png", dpi=160)
    print("wrote deficit_spectrum.png")


if __name__ == "__main__":
    main()
